import { getLocale } from "next-intl/server";

import { redirect } from "@/i18n/navigation";

/**
 * `/chat` landing — redirects into a freshly-minted conversation id.
 *
 * No `conversations` row is created here. The row is created lazily
 * by `app/api/chat/route.ts` on the first POST for this id, so
 * visiting `/chat` and then never sending a message leaves nothing
 * behind (ADR-0009: conversations are a persistence concern the route
 * owns, not a page-load side effect).
 */
export default async function ChatIndexPage() {
  const locale = await getLocale();
  redirect({ href: `/chat/${crypto.randomUUID()}`, locale });
}

import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { Chat } from "@/components/chat/chat-panel";
import { ConversationHeader } from "@/components/chat/conversation-header";
import { ConversationSidebar } from "@/components/chat/conversation-sidebar";
import {
  listConversationHistory,
  loadConversationForChat,
} from "@/actions/chat";
import { getChatQuotaState } from "@/lib/chat-quota";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("chat");
  return { title: t("conversationPage.title") };
}

/**
 * `dynamic = "force-dynamic"`: `loadConversationForChat`/
 * `listConversationHistory` read request-scoped session and workspace
 * state (`requireWorkspace()`, inside `@/actions/chat`), so this page
 * can only ever render per-request.
 */
export const dynamic = "force-dynamic";

interface ConversationPageProps {
  params: Promise<{ id: string; locale: string }>;
}

export default async function ConversationPage({
  params,
}: ConversationPageProps) {
  const { id } = await params;
  const t = await getTranslations("chat");

  // In parallel: the quota read is an estimate that holds no credit,
  // so it cannot slow down or interfere with loading the conversation.
  const [conversationResult, historyResult, quotaState] = await Promise.all([
    loadConversationForChat(id),
    listConversationHistory(),
    getChatQuotaState(),
  ]);

  if (!conversationResult.success) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 p-8 text-center">
        <h1 className="text-lg font-semibold">
          {t("conversationPage.unavailableTitle")}
        </h1>
        <p className="text-sm text-muted-foreground">
          {conversationResult.error}
        </p>
      </div>
    );
  }

  const { conversation, messages } = conversationResult.data;
  const conversations = historyResult.success ? historyResult.data : [];
  // The header's dropdown is the small-screen fallback for the
  // sidebar, and there it lists somewhere to go — so the conversation
  // already on screen is filtered out of it, but not out of the
  // sidebar, which highlights it instead.
  const history = conversations.filter((item) => item.id !== id);

  return (
    <div className="flex h-full">
      <ConversationSidebar conversations={conversations} activeId={id} />

      <div className="flex min-w-0 flex-1 flex-col">
        <ConversationHeader
          conversationId={id}
          title={conversation?.title ?? null}
          history={history}
        />
        <Chat
          conversationId={id}
          initialMessages={messages}
          quotaState={quotaState}
        />
      </div>
    </div>
  );
}

import { Skeleton } from "@/components/ui/skeleton";

export default function ConversationLoading() {
  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b px-4 py-3">
        <Skeleton className="h-5 w-40" />
        <Skeleton className="h-8 w-24" />
      </div>
      <div className="flex-1 space-y-6 px-4 py-6">
        <div className="mx-auto flex max-w-3xl flex-col gap-6">
          <Skeleton className="ml-auto h-10 w-2/3 rounded-2xl" />
          <Skeleton className="h-24 w-3/4 rounded-lg" />
          <Skeleton className="ml-auto h-10 w-1/2 rounded-2xl" />
        </div>
      </div>
    </div>
  );
}

"use server";

/**
 * Chat conversation actions — thin transport over
 * `@intelligo-dev/core/conversations` (ADR-0009): resolve the caller's actor
 * via `requireWorkspace()`, call the core service, map any
 * `ConversationServiceError` to a friendly message, and reshape the
 * result for the page and its client components. Sending a message and
 * streaming a reply is NOT here — that is `app/api/chat/route.ts`,
 * because streaming needs a Route Handler, not a Server Action.
 *
 * `loadConversationForChat` is the one read that treats `not_found` as
 * success rather than failure: `app/[locale]/(app)/chat/page.tsx`
 * redirects to `/chat/<uuid>` without creating a row (see its doc
 * comment), so the very first render of a brand-new conversation
 * legitimately has no `conversations` row yet — the route handler
 * creates it on the first POST. Every other action here treats
 * `not_found`/`forbidden` as a genuine failure.
 */

import { getTranslations } from "next-intl/server";
import { revalidatePath } from "next/cache";

import { requireWorkspace } from "@intelligo-dev/auth";
import { toUIMessages } from "@intelligo-dev/chat";
import { saveDocument } from "@intelligo-dev/core/documents";
import {
  deleteConversation as deleteConversationRow,
  getConversation,
  getMessages,
  isConversationServiceError,
  listConversations,
  renameConversation as renameConversationRow,
} from "@intelligo-dev/core/conversations";

export type ChatActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

type Translator = Awaited<ReturnType<typeof getTranslations>>;

function friendlyMessageKey(code: string): string | undefined {
  switch (code) {
    case "not_found":
      return "actions.conversationNotFound";
    case "forbidden":
      return "actions.conversationForbidden";
    case "invalid_input":
      return "actions.invalidTitle";
    case "database_error":
      return "actions.databaseError";
    default:
      return undefined;
  }
}

function friendlyError(t: Translator, error: unknown): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isConversationServiceError(error)) {
    const key = friendlyMessageKey(error.code);
    return key ? t(key) : t("actions.genericError");
  }
  return t("actions.genericError");
}

async function actor() {
  const { workspace, user } = await requireWorkspace();
  return { workspaceId: workspace.id, userId: user.id };
}

export type ConversationSummary = {
  id: string;
  title: string | null;
  updatedAt: string;
};

/** Recent conversations for the sidebar and history dropdown, most recently updated first. */
export async function listConversationHistory(): Promise<
  ChatActionResult<ConversationSummary[]>
> {
  try {
    // Enough to fill a sidebar and be worth searching. The cap is
    // deliberate: past a few hundred, filtering belongs in a query,
    // not in the browser (see `conversation-sidebar.tsx`).
    const rows = await listConversations(await actor(), { limit: 100 });
    return {
      success: true,
      data: rows.map((row) => ({
        id: row.id,
        title: row.title,
        updatedAt: row.updatedAt.toISOString(),
      })),
    };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export type LoadedConversation = {
  conversation: { id: string; title: string | null } | null;
  messages: ReturnType<typeof toUIMessages>;
};

/**
 * Loads a conversation and its messages for `<Chat>`'s initial state.
 * A conversation id with no row yet resolves as a brand-new, empty
 * chat rather than an error — see the module doc comment above.
 */
export async function loadConversationForChat(
  id: string
): Promise<ChatActionResult<LoadedConversation>> {
  try {
    const scoped = await actor();

    try {
      const conversation = await getConversation(scoped, id);
      const rows = await getMessages(scoped, id);
      return {
        success: true,
        data: {
          conversation: { id: conversation.id, title: conversation.title },
          // Stored parts are a JSON string; a corrupt row costs one
          // message, not the conversation.
          messages: toUIMessages(rows),
        },
      };
    } catch (error) {
      if (isConversationServiceError(error) && error.code === "not_found") {
        return { success: true, data: { conversation: null, messages: [] } };
      }
      throw error;
    }
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function renameConversation(
  id: string,
  title: string
): Promise<ChatActionResult<{ title: string | null }>> {
  try {
    const updated = await renameConversationRow(await actor(), id, title);
    return { success: true, data: { title: updated.title } };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

export async function deleteConversation(
  id: string
): Promise<ChatActionResult<undefined>> {
  try {
    await deleteConversationRow(await actor(), id);
    return { success: true, data: undefined };
  } catch (error) {
    return {
      success: false,
      error: friendlyError(await getTranslations("chat"), error),
    };
  }
}

/**
 * Saves one assistant reply as a document artifact, so a useful answer
 * doesn't only live in a conversation. This is the manual counterpart
 * to a `saveArtifact` tool: same destination (`@intelligo-dev/core`'s
 * document persistence, ADR-0009), same `/artifacts` page, just driven
 * by the reader instead of the model.
 *
 * The message id becomes the document id, which makes saving the same
 * reply twice a new *version* of one artifact rather than a duplicate.
 */
export async function saveMessageAsArtifact(params: {
  messageId: string;
  content: string;
  title?: string;
}): Promise<ChatActionResult<{ id: string; title: string }>> {
  const t = await getTranslations("chat");

  const content = params.content.trim();
  if (!content) {
    return { success: false, error: t("actions.emptyArtifact") };
  }

  const title = params.title?.trim() || deriveArtifactTitle(content);

  try {
    const saved = await saveDocument(await actor(), {
      id: params.messageId,
      title,
      content,
      kind: "text",
    });
    revalidatePath("/artifacts");
    return { success: true, data: { id: saved.id, title: saved.title } };
  } catch (error) {
    return { success: false, error: friendlyError(t, error) };
  }
}

const MAX_ARTIFACT_TITLE = 60;

/** First line of the reply, trimmed to something list-sized. */
function deriveArtifactTitle(content: string): string {
  const line =
    content
      .split("\n")
      .map((value) => value.replace(/^#+\s*/, "").trim())
      .find(Boolean) ?? "";
  if (!line) return "Untitled";
  return line.length <= MAX_ARTIFACT_TITLE
    ? line
    : `${line.slice(0, MAX_ARTIFACT_TITLE - 1).trimEnd()}…`;
}

import "server-only";

/**
 * Consumer-owned model resolution for the chat transport.
 *
 * A fresh install has no AI provider keys, so `getChatModel` returns
 * the framework's deterministic stub (`@intelligo-dev/chat/testing`): it
 * echoes the last user message back through a real token-by-token
 * stream. No network call, no API key, and the app still builds,
 * boots and streams a real `createUIMessageStream` response end to end.
 *
 * `CHAT_MODEL_ID` is deliberately a real, registered id
 * (`@intelligo-dev/executions/pricing`) even though the stub never calls
 * that provider: the execution boundary bills whatever id the transport
 * settles with (ADR-0003), and an id with no registered price is
 * refused at admission. Using a real id here means a clean install
 * exercises the *correct* pricing path — swap in your own model id the
 * moment you swap in a real provider below, and keep it one that is
 * registered.
 *
 * To use a real provider: install its AI SDK package (e.g.
 * `pnpm add @ai-sdk/anthropic` in this app) and replace the body of
 * `getChatModel` — the commented example below is the whole change.
 */

import type { LanguageModel } from "ai";
import { createStubLanguageModel } from "@intelligo-dev/chat/testing";
import { cookies } from "next/headers";
import { getTranslations } from "next-intl/server";

import { routing } from "@/i18n/routing";

/** Must be a registered model id in `@intelligo-dev/executions/pricing`. */
export const CHAT_MODEL_ID = "google/gemini-2.5-flash";

/**
 * The stub replies in the caller's locale. This file lives outside the
 * `[locale]` segment, so the locale comes from the `NEXT_LOCALE` cookie
 * next-intl's middleware sets on every page navigation.
 */
async function resolveLocale(): Promise<string> {
  const cookieName =
    typeof routing.localeCookie === "object"
      ? (routing.localeCookie.name ?? "NEXT_LOCALE")
      : "NEXT_LOCALE";
  const value = (await cookies()).get(cookieName)?.value;
  const locales: readonly string[] = routing.locales;
  return value && locales.includes(value) ? value : routing.defaultLocale;
}

/**
 * Resolves the language model for a chat turn. `modelId` is unused by
 * the stub (it only ever returns one model) — a real implementation
 * switches on it, e.g.:
 *
 *   import { anthropic } from "@ai-sdk/anthropic";
 *
 *   export function getChatModel(modelId: string): LanguageModel {
 *     if (modelId === CHAT_MODEL_ID) return anthropic("claude-sonnet-4-6-20260214");
 *     return anthropic("claude-sonnet-4-6-20260214");
 *   }
 *
 * and `CHAT_MODEL_ID` above becomes whatever registered id matches the
 * provider model string you pass.
 */
export function getChatModel(modelId: string): LanguageModel {
  void modelId;
  return createStubLanguageModel({
    modelId: CHAT_MODEL_ID,
    reply: async (userText) => {
      const t = await getTranslations({
        locale: await resolveLocale(),
        namespace: "chat",
      });
      return `${t("stub.preface")}\n\n${t("stub.youSaid")} "${userText}"`;
    },
  });
}

"use client";

/**
 * Tool-call renderer seam.
 *
 * `@intelligo-dev/chat`'s dissolving package (ADR-0008) kept a runtime
 * `Map` that a product registered into at client bootstrap — a
 * package-level registry a consumer could never see, let alone edit.
 * This item's replacement is the opposite of clever: `TOOL_RENDERERS`
 * below is a plain object literal in source you own. Add a tool name
 * → component entry to it directly; there is no `register()` call to
 * invoke from a composition root, and nothing here runs as an import
 * side effect, so ADR-0005 has nothing to enforce against this file.
 *
 * A tool with no entry falls back to `DefaultToolCard`: the design
 * system's T3 Tool part — name, state, and the raw input and output. It exists so
 * a new tool call always renders *something* honest while you're
 * wiring up its real card — it is not meant to be your product's
 * shipped UI for that tool.
 *
 * `components/chat/message.tsx` calls `getToolRenderer(toolName)` for
 * every `tool-*`/`dynamic-tool` part it renders.
 */

import type { ComponentType } from "react";
import type { ToolUIPart } from "ai";
import { useTranslations } from "next-intl";
import { FileTextIcon } from "lucide-react";

import {
  Tool,
  ToolContent,
  ToolHeader,
  ToolInput,
  ToolOutput,
} from "@/components/ui/ai-tool";
import { Button } from "@/components/ui/button";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item";
import { Link } from "@/i18n/navigation";

/**
 * Mirrors the AI SDK's `ToolUIPart`/`DynamicToolUIPart` state union
 * (`ai`'s `dist/index.d.ts`) structurally rather than importing it, so
 * this file doesn't pin a consumer to the SDK's exact tool-generics
 * shape. The three `approval-*`/`output-denied` states only appear for
 * tools using the SDK's human-in-the-loop approval flow — a plain tool
 * never produces them.
 */
export type ToolPartState =
  | "input-streaming"
  | "input-available"
  | "approval-requested"
  | "approval-responded"
  | "output-available"
  | "output-error"
  | "output-denied";

/**
 * What a renderer can do back to the conversation. Passed to every
 * renderer, so an *interactive* tool card — approve/deny, pick one of
 * several options, submit a form the tool asked for — is possible
 * without reaching around the component tree.
 *
 * `addToolResult` answers the tool call the card is rendering (pass
 * its `toolCallId`); `sendMessage` sends a new user turn instead.
 */
export interface ToolRendererActions {
  sendMessage: (text: string) => void;
  addToolResult: (args: {
    tool: string;
    toolCallId: string;
    output: unknown;
  }) => void;
}

export interface ToolRendererProps {
  toolName: string;
  state: ToolPartState;
  input?: unknown;
  output?: unknown;
  errorText?: string;
  /** The AI SDK's id for this call — required by `addToolResult`. */
  toolCallId?: string;
  /** Present when the message list passes them; see above. */
  actions?: ToolRendererActions;
}

/**
 * Map of AI SDK tool name → the component that renders its call and
 * result.
 *
 * Ships with one entry: `saveArtifact`, the convention this catalogue
 * uses for "the assistant produced a document." Bind a tool of that
 * name in `@/lib/chat-server-config` and its result renders as a card
 * linking into the `artifacts` page. Rename the key if your tool is
 * called something else.
 *
 * Add your own the same way — this is a plain object literal in source
 * you own, with no `register()` call anywhere:
 *
 *   import { WeatherCard } from "@/components/chat/weather-card";
 *
 *   export const TOOL_RENDERERS: Record<string, ComponentType<ToolRendererProps>> = {
 *     saveArtifact: ArtifactLinkCard,
 *     getWeather: WeatherCard,
 *   };
 */
export const TOOL_RENDERERS: Record<
  string,
  ComponentType<ToolRendererProps>
> = {
  saveArtifact: ArtifactLinkCard,
};

export function getToolRenderer(
  toolName: string
): ComponentType<ToolRendererProps> {
  return TOOL_RENDERERS[toolName] ?? DefaultToolCard;
}

/** Maps a tool part's state to its `chat.toolCard.*` message key. */
const STATE_MESSAGE_KEY: Record<ToolPartState, string> = {
  "input-streaming": "toolCard.calling",
  "input-available": "toolCard.running",
  "approval-requested": "toolCard.needsApproval",
  "approval-responded": "toolCard.approved",
  "output-available": "toolCard.done",
  "output-error": "toolCard.error",
  "output-denied": "toolCard.denied",
};

function toolLabel(toolName: string): string {
  const spaced = toolName.replace(/([a-z0-9])([A-Z])/g, "$1 $2");
  return spaced.charAt(0).toUpperCase() + spaced.slice(1).toLowerCase();
}

export function DefaultToolCard({
  toolName,
  state,
  input,
  output,
  errorText,
}: ToolRendererProps) {
  const t = useTranslations("chat");

  return (
    <Tool className="max-w-xl">
      <ToolHeader
        title={toolLabel(toolName)}
        type={`tool-${toolName}`}
        state={state as ToolUIPart["state"]}
        stateLabel={t(STATE_MESSAGE_KEY[state])}
      />
      <ToolContent>
        {input !== undefined ? (
          <ToolInput input={input} label={t("toolCard.input")} />
        ) : null}
        <ToolOutput
          output={output}
          errorText={errorText}
          label={errorText ? t("toolCard.errorHeading") : t("toolCard.output")}
        />
      </ToolContent>
    </Tool>
  );
}

/**
 * Renderer for a tool that produced a document artifact. Expects the
 * tool's output to carry a `title` (and optionally a `documentId`);
 * anything else falls back to the generic card, so a tool whose shape
 * drifts renders honestly rather than blank.
 *
 * This is the chat↔artifacts affordance: a reply that generated a
 * document says so inline, and links to where the document lives.
 */
export function ArtifactLinkCard({
  toolName,
  state,
  input,
  output,
  errorText,
}: ToolRendererProps) {
  const t = useTranslations("chat");

  const title =
    output && typeof output === "object" && "title" in output
      ? String((output as { title: unknown }).title)
      : undefined;

  if (state !== "output-available" || !title) {
    return (
      <DefaultToolCard
        toolName={toolName}
        state={state}
        input={input}
        output={output}
        errorText={errorText}
      />
    );
  }

  return (
    <Item variant="outline" size="sm" className="max-w-xl">
      <ItemMedia variant="icon">
        <FileTextIcon />
      </ItemMedia>
      <ItemContent>
        <ItemTitle>{title}</ItemTitle>
        <ItemDescription>{t("artifactCard.saved")}</ItemDescription>
      </ItemContent>
      <ItemActions>
        <Button
          size="sm"
          variant="outline"
          render={<Link href="/artifacts" />}
          nativeButton={false}
        >
          {t("artifactCard.open")}
        </Button>
      </ItemActions>
    </Item>
  );
}

"use client";

/**
 * Chat — client root. Owns streaming state via the AI SDK's `useChat`
 * (`@ai-sdk/react`), talking to `app/api/chat/route.ts` over a
 * `DefaultChatTransport`. `initialMessages` comes from the server
 * component (`app/[locale]/(app)/chat/[id]/page.tsx`, via
 * `@/actions/chat`) so reloading a conversation shows its history
 * immediately, with no client-side fetch-on-mount.
 *
 * A `?query=` search param seeds the first turn: another surface (the
 * dashboard's prompt bar, a marketing CTA) can mint a conversation id
 * and link straight into a started conversation. It is sent once, only
 * into an empty conversation, so a refresh doesn't replay it.
 */

import { useEffect, useMemo, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { DefaultChatTransport } from "ai";
import { useChat } from "@ai-sdk/react";
import type { UIMessage } from "ai";
import { useSearchParams } from "next/navigation";

import { Alert, AlertDescription } from "@/components/ui/alert";

import { ChatInput } from "./chat-input";
import { MessageList } from "./message-list";
import {
  CreditStatusBanner,
  type ChatBlock,
  type ChatQuotaState,
} from "./credit-status-banner";
import { parseChatError } from "@intelligo-dev/chat/client";

import { chatConfig } from "@/lib/chat-config";
import type { ToolRendererActions } from "@/lib/chat-renderers";

/**
 * A refusal that blocks the composer, or nothing. Admission answers 402
 * with the entitlement port's own code (`insufficient_credits`,
 * `allowance_depleted`…), which is what the banner keys its copy on; a
 * feature gate is a block too. Anything else — a rate limit, a stream
 * failure — is transient and belongs in the error strip.
 *
 * At module scope so the effect that reads it has a stable reference
 * and needs no dependency entry.
 */
function refusalFrom(chatError: Error): ChatBlock | null {
  const parsed = parseChatError(chatError);
  if (!parsed) return null;
  if (
    parsed.code !== "QUOTA_EXCEEDED" &&
    parsed.code !== "BILLING_NOT_CONFIGURED" &&
    parsed.code !== "FEATURE_GATED"
  ) {
    return null;
  }
  return { code: parsed.reasonCode ?? parsed.code, message: parsed.error };
}

interface ChatProps {
  conversationId: string;
  initialMessages: UIMessage[];
  /**
   * Server-rendered credit state. Optional so a deployment that has
   * not wired billing renders the chat unchanged.
   */
  quotaState?: ChatQuotaState | null;
}

export function Chat({
  conversationId,
  initialMessages,
  quotaState = null,
}: ChatProps) {
  const t = useTranslations("chat");
  // Namespace-less: `chatConfig.starters` entries are fully-qualified
  // message keys into the app's whole message tree (see
  // `@/lib/chat-config`'s doc comment), not keys under this item's own
  // "chat" namespace.
  const tAny = useTranslations();
  const searchParams = useSearchParams();

  const transport = useMemo(
    () =>
      new DefaultChatTransport({
        api: "/api/chat",
        // The agent identity travels with the turn so a deployment that
        // resolves agents per conversation (`resolveAgent` in
        // `lib/chat-server-config.ts`) knows which one this surface is.
        body: {
          id: conversationId,
          ...(chatConfig.agent?.id ? { agentId: chatConfig.agent.id } : {}),
        },
      }),
    [conversationId]
  );

  const {
    messages,
    sendMessage,
    regenerate,
    addToolResult,
    status,
    stop,
    error,
  } = useChat({
    id: conversationId,
    messages: initialMessages,
    transport,
    sendAutomaticallyWhen: chatConfig.sendAutomaticallyWhen,
  });

  const isStreaming = status === "streaming" || status === "submitted";

  /**
   * A refusal the route returned mid-conversation.
   *
   * The server-rendered state is what the page opened with; the
   * balance can run out three turns later, and the reader should not
   * have to reload to be told.
   */
  const [block, setBlock] = useState<ChatBlock | null>(null);
  const blocked = block !== null || quotaState?.allowed === false;

  const starters = useMemo(
    () => (chatConfig.starters ?? []).map((key) => tAny(key)),
    [tAny]
  );

  // In an effect, not in render: `useChat` surfaces the error as
  // state, and setting state while rendering from it is how a render
  // loop starts.
  useEffect(() => {
    if (!error) return;
    const refusal = refusalFrom(error);
    if (refusal) setBlock(refusal);
  }, [error]);

  function friendlyChatError(chatError: Error): string {
    // A non-JSON error response (a proxy's page, a network failure)
    // surfaces as raw text; the generic copy beats showing it.
    return parseChatError(chatError)?.error ?? t("error.generic");
  }

  function handleSend(text: string) {
    if (!text.trim() || isStreaming || blocked) return;
    void sendMessage({ text });
  }

  // Prefill from `?query=`, once, and only into a conversation that has
  // no messages yet.
  const prefillSent = useRef(false);
  useEffect(() => {
    if (prefillSent.current) return;
    const query = searchParams.get("query");
    if (!query || messages.length > 0) return;
    prefillSent.current = true;
    void sendMessage({ text: query });
  }, [searchParams, messages.length, sendMessage]);

  // Rebuilt each render on purpose: `handleSend` closes over
  // `isStreaming`, and nothing downstream is memoized on this object.
  const toolActions: ToolRendererActions = {
    sendMessage: handleSend,
    addToolResult: (args) => void addToolResult(args),
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <MessageList
        messages={messages}
        isStreaming={status === "streaming"}
        starters={starters}
        onStarterSelect={handleSend}
        onRetry={isStreaming ? undefined : () => void regenerate()}
        toolActions={toolActions}
      />
      <CreditStatusBanner quotaState={quotaState} block={block} />
      {error && !block ? (
        <Alert variant="destructive" className="mx-auto mb-2 w-full max-w-3xl">
          <AlertDescription>{friendlyChatError(error)}</AlertDescription>
        </Alert>
      ) : null}
      <ChatInput
        onSend={handleSend}
        onStop={stop}
        isStreaming={isStreaming}
        disabled={blocked}
        disabledPlaceholder={t("input.blockedPlaceholder")}
      />
    </div>
  );
}

