}

function EmptyState({
  starters,
  onStarterSelect,
}: {
  starters?: string[];
  onStarterSelect?: (text: string) => void;
}) {
  const t = useTranslations("chat");

  return (
    <Empty className="flex-1">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <MessageSquareIcon />
        </EmptyMedia>
        <EmptyTitle>{t("emptyState.title")}</EmptyTitle>
        <EmptyDescription>{t("emptyState.description")}</EmptyDescription>
      </EmptyHeader>
      {starters && starters.length > 0 ? (
        <EmptyContent className="max-w-2xl flex-row flex-wrap justify-center">
          {starters.map((starter, index) => (
            <Suggestion
              key={index}
              suggestion={starter}
              onClick={onStarterSelect}
              className="h-auto py-1.5 text-left whitespace-normal"
            />
          ))}
        </EmptyContent>
      ) : null}
    </Empty>
  );
}

"use client";

/**
 * Renders one `UIMessage`'s parts on the design system's conversation
 * components (ADR-0013): shadcn's Message and Bubble for the turn, the
 * T3 Reasoning part for reasoning, and `@/lib/chat-renderers`'s seam for
 * tool calls. Text renders with `streamdown`, the markdown-while-
 * streaming renderer, because replies are routinely lists, code and
 * headings arriving a token at a time.
 *
 * A finished assistant message carries an action row — copy the reply,
 * regenerate it (last message only), and save it as an artifact so the
 * `artifacts` item's page has something to show. The row is hidden
 * while that message is still streaming.
 */

import { useTransition } from "react";
import { getToolName, isReasoningUIPart, isTextUIPart, isToolUIPart } from "ai";
import type { UIMessage } from "ai";
import { useTranslations } from "next-intl";
import { BotIcon, FileDownIcon, RefreshCwIcon, UserIcon } from "lucide-react";
import { Streamdown } from "streamdown";
import { toast } from "sonner";

import {
  Reasoning,
  ReasoningContent,
  ReasoningTrigger,
} from "@/components/ui/ai-reasoning";
import { Bubble, BubbleContent } from "@/components/ui/bubble";
import { Button } from "@/components/ui/button";
import { CopyButton } from "@/components/ui/copy-button";
import {
  MessageAvatar,
  MessageContent,
  MessageFooter,
  Message as MessageRoot,
} from "@/components/ui/message";
import { Spinner } from "@/components/ui/spinner";
import {
  getToolRenderer,
  type ToolRendererActions,
} from "@/lib/chat-renderers";
import { saveMessageAsArtifact } from "@/actions/chat";

interface MessageProps {
  message: UIMessage;
  isLastMessage: boolean;
  isStreaming: boolean;
  /** Regenerate the last assistant reply; omit to hide the control. */
  onRetry?: () => void;
  toolActions?: ToolRendererActions;
}

/** The message's plain text, for copying and for artifact content. */
function messageText(message: UIMessage): string {
  return message.parts
    .filter(isTextUIPart)
    .map((part) => part.text)
    .join("\n\n")
    .trim();
}

export function Message({
  message,
  isLastMessage,
  isStreaming,
  onRetry,
  toolActions,
}: MessageProps) {
  const t = useTranslations("chat");
  const isUser = message.role === "user";
  const isEmptyAssistant =
    !isUser && message.parts.every((part) => !isTextUIPart(part) || !part.text);
  const isStreamingThis = isLastMessage && isStreaming;
  const text = messageText(message);
  const showActions = !isUser && !isStreamingThis && text.length > 0;

  return (
    <MessageRoot
      align={isUser ? "end" : "start"}
      className="group/chat-message"
    >
      <MessageAvatar>{isUser ? <UserIcon /> : <BotIcon />}</MessageAvatar>

      <MessageContent>
        {message.parts.map((part, index) => {
          const key = `${message.id}-${index}`;

          if (isTextUIPart(part)) {
            if (!part.text) return null;
            return isUser ? (
              <Bubble key={key} align="end">
                <BubbleContent className="whitespace-pre-wrap">
                  {part.text}
                </BubbleContent>
              </Bubble>
            ) : (
              <Bubble key={key} variant="ghost">
                <BubbleContent>
                  <Streamdown>{part.text}</Streamdown>
                </BubbleContent>
              </Bubble>
            );
          }

          if (isReasoningUIPart(part)) {
            if (!part.text) return null;
            const reasoningStreaming =
              isStreamingThis && index === message.parts.length - 1;
            return (
              <Reasoning key={key} isStreaming={reasoningStreaming}>
                <ReasoningTrigger
                  getThinkingMessage={(streaming, duration) =>
                    streaming
                      ? t("message.thinking")
                      : duration === undefined
                        ? t("message.thoughtBriefly")
                        : t("message.thoughtFor", { seconds: duration })
                  }
                />
                <ReasoningContent>{part.text}</ReasoningContent>
              </Reasoning>
            );
          }

          if (isToolUIPart(part)) {
            const toolName = getToolName(part);
            const Renderer = getToolRenderer(toolName);
            const state = part.state;
            return (
              <Renderer
                key={key}
                toolName={toolName}
                state={state}
                input={"input" in part ? part.input : undefined}
                output={state === "output-available" ? part.output : undefined}
                errorText={
                  state === "output-error" ? part.errorText : undefined
                }
                toolCallId={"toolCallId" in part ? part.toolCallId : undefined}
                actions={toolActions}
              />
            );
          }

          return null;
        })}

        {isStreamingThis && isEmptyAssistant ? (
          <span role="status" className="shimmer text-sm text-muted-foreground">
            {t("message.thinking")}
          </span>
        ) : null}

        {showActions ? (
          <MessageFooter>
            <MessageActions
              text={text}
              messageId={message.id}
              onRetry={isLastMessage ? onRetry : undefined}
            />
          </MessageFooter>
        ) : null}
      </MessageContent>
    </MessageRoot>
  );
}

function MessageActions({
  text,
  messageId,
  onRetry,
}: {
  text: string;
  messageId: string;
  onRetry?: () => void;
}) {
  const t = useTranslations("chat");
  const [isSaving, startSaving] = useTransition();

  function handleSave() {
    startSaving(async () => {
      const result = await saveMessageAsArtifact({ messageId, content: text });
      if (result.success) {
        toast.success(t("actions.savedToArtifacts"));
      } else {
        toast.error(result.error);
      }
    });
  }

  return (
    <div className="flex items-center gap-1 opacity-0 transition-opacity group-hover/chat-message:opacity-100 focus-within:opacity-100">
      <CopyButton
        value={text}
        label={t("actions.copy")}
        copiedLabel={t("actions.copied")}
        onCopyError={() => toast.error(t("actions.copyFailed"))}
        size="xs"
        className="text-muted-foreground"
      >
        {t("actions.copy")}
      </CopyButton>

      {onRetry ? (
        <Button
          type="button"
          variant="ghost"
          size="xs"
          className="text-muted-foreground"
          onClick={onRetry}
        >
          <RefreshCwIcon data-icon="inline-start" />
          {t("actions.retry")}
        </Button>
      ) : null}

      <Button
        type="button"
        variant="ghost"
        size="xs"
        className="text-muted-foreground"
        onClick={handleSave}
        disabled={isSaving}
        aria-busy={isSaving || undefined}
      >
        {isSaving ? (
          <Spinner data-icon="inline-start" />
        ) : (
          <FileDownIcon data-icon="inline-start" />
        )}
        {t("actions.save")}
      </Button>
    </div>
  );
}

"use client";

/**
 * The composer, on the T3 prompt input (ADR-0013): an autosizing
 * textarea that sends on Enter and a submit that becomes stop while a
 * reply streams.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import {
  PromptInput,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputTools,
} from "@/components/ui/ai-prompt-input";

interface ChatInputProps {
  onSend: (text: string) => void;
  onStop: () => void;
  isStreaming: boolean;
  /**
   * Stops the composer accepting a turn that will be refused — out of
   * credits, or behind a feature gate. The banner above says why; this
   * is what keeps someone from writing a paragraph into a request the
   * route has already told us it will reject.
   */
  disabled?: boolean;
  /** Placeholder to show instead of the usual one while disabled. */
  disabledPlaceholder?: string;
}

export function ChatInput({
  onSend,
  onStop,
  isStreaming,
  disabled = false,
  disabledPlaceholder,
}: ChatInputProps) {
  const t = useTranslations("chat");
  const [value, setValue] = useState("");
  const placeholder =
    disabled && disabledPlaceholder
      ? disabledPlaceholder
      : t("input.placeholder");

  return (
    <div className="bg-background px-4 pt-2 pb-4">
      <PromptInput
        className="mx-auto max-w-3xl"
        onSubmit={({ text }) => {
          const trimmed = text.trim();
          if (!trimmed || isStreaming || disabled) return;
          onSend(trimmed);
          setValue("");
        }}
      >
        <PromptInputTextarea
          value={value}
          onChange={(event) => setValue(event.target.value)}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={placeholder}
        />
        <PromptInputFooter>
          <PromptInputTools />
          <PromptInputSubmit
            status={isStreaming ? "streaming" : "ready"}
            label={isStreaming ? t("input.stop") : t("input.send")}
            disabled={!isStreaming && (disabled || !value.trim())}
            onClick={isStreaming ? onStop : undefined}
          />
        </PromptInputFooter>
      </PromptInput>
    </div>
  );
}

"use client";

/**
 * Conversation header — title with inline rename, a history dropdown
 * for switching conversations, a "New chat" link, and delete.
 *
 * The history dropdown and "New chat" here are the small-screen
 * controls: from `lg` up, `ConversationSidebar` shows the same list
 * permanently and both are hidden rather than duplicated.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import {
  CheckIcon,
  ChevronDownIcon,
  PencilIcon,
  PlusIcon,
  Trash2Icon,
  XIcon,
} from "lucide-react";
import { toast } from "sonner";

import { Link, useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

import { deleteConversation, renameConversation } from "@/actions/chat";
import type { ConversationSummary } from "@/actions/chat";
import { chatConfig } from "@/lib/chat-config";

interface ConversationHeaderProps {
  conversationId: string;
  title: string | null;
  history: ConversationSummary[];
}

export function ConversationHeader({
  conversationId,
  title,
  history,
}: ConversationHeaderProps) {
  const t = useTranslations("chat");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [isEditing, setIsEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState(title ?? "");
  const HeaderRight = chatConfig.headerRight;
  const agentName = chatConfig.agent?.name ?? t("agent.defaultName");
  const agentIcon = chatConfig.agent?.icon;

  function startEditing() {
    setDraftTitle(title ?? "");
    setIsEditing(true);
  }

  function commitRename() {
    const trimmed = draftTitle.trim();
    setIsEditing(false);
    if (!trimmed || trimmed === title) return;

    startTransition(async () => {
      const result = await renameConversation(conversationId, trimmed);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.refresh();
    });
  }

  function handleDelete() {
    startTransition(async () => {
      const result = await deleteConversation(conversationId);
      if (!result.success) {
        toast.error(result.error);
        return;
      }
      router.push("/chat");
    });
  }

  return (
    <header className="flex items-center justify-between gap-2 border-b px-4 py-3">
      <div className="flex min-w-0 flex-1 items-center gap-1">
        <span className="mr-1 flex shrink-0 items-center gap-1 text-xs text-muted-foreground">
          {agentIcon ? <span aria-hidden>{agentIcon}</span> : null}
          <span className="max-w-24 truncate">{agentName}</span>
        </span>
        {isEditing ? (
          <>
            <Input
              autoFocus
              value={draftTitle}
              onChange={(event) => setDraftTitle(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") commitRename();
                if (event.key === "Escape") setIsEditing(false);
              }}
              className="h-8 max-w-xs"
            />
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={commitRename}
              aria-label={t("header.renameSave")}
            >
              <CheckIcon />
            </Button>
            <Button
              size="icon-sm"
              variant="ghost"
              className="shrink-0"
              onClick={() => setIsEditing(false)}
              aria-label={t("header.renameCancel")}
            >
              <XIcon />
            </Button>
          </>
        ) : (
          <>
            <h1 className="truncate text-sm font-medium">
              {title || t("header.newChatTitle")}
            </h1>
            <Button
              size="icon-xs"
              variant="ghost"
              className="shrink-0"
              onClick={startEditing}
              aria-label={t("header.renameEdit")}
            >
              <PencilIcon />
            </Button>
          </>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-2">
        {HeaderRight ? <HeaderRight conversationId={conversationId} /> : null}

        {/* Below `lg` this is the only way to reach history; at `lg`
            and up `ConversationSidebar` shows the same list. */}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button variant="outline" size="sm" className="gap-1 lg:hidden" />
            }
          >
            {t("header.historyTrigger")}
            <ChevronDownIcon data-icon="inline-end" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-64">
            {history.length === 0 ? (
              <div className="px-2 py-1.5 text-sm text-muted-foreground">
                {t("header.historyEmpty")}
              </div>
            ) : (
              history.map((item) => (
                <DropdownMenuItem
                  key={item.id}
                  render={
                    <Link href={`/chat/${item.id}`} className="truncate" />
                  }
                >
                  {item.title || t("header.historyUntitled")}
                </DropdownMenuItem>
              ))
            )}
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="outline"
          size="sm"
          className="lg:hidden"
          render={<Link href="/chat" />}
          nativeButton={false}
        >
          <PlusIcon data-icon="inline-start" />
          {t("header.newChat")}
        </Button>

        {/* Confirmed: deleting a conversation is unrecoverable, and
            this control sits one pixel from "New chat". */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                className="text-muted-foreground hover:text-destructive"
                disabled={isPending}
                aria-label={t("header.delete")}
              />
            }
          >
            {isPending ? <Spinner /> : <Trash2Icon />}
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{t("deleteDialog.title")}</AlertDialogTitle>
              <AlertDialogDescription>
                {t("deleteDialog.description")}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>{t("deleteDialog.cancel")}</AlertDialogCancel>
              <AlertDialogAction onClick={handleDelete}>
                {t("deleteDialog.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
    </header>
  );
}

"use client";

/**
 * Persistent conversation history beside the chat.
 *
 * The header's dropdown was fine while a workspace had a handful of
 * conversations and stopped being fine somewhere around thirty: no
 * search, no sense of when anything happened, and the current
 * conversation invisible in the list. This puts history where a chat
 * product keeps it — always on screen, grouped by recency, filterable.
 *
 * Below `lg` it is hidden and the header's dropdown takes over: a
 * fixed sidebar on a phone costs more than it returns, and the two
 * controls read the same data, so nothing is lost.
 *
 * Filtering is client-side over what the server already sent. That is
 * honest for the sizes this list actually reaches; a workspace with
 * thousands of conversations wants a server-side search action, and
 * this component's props are shaped so adding one later replaces the
 * filter without touching the layout.
 */

import { useMemo, useState } from "react";
import { MessageSquareIcon, PlusIcon, SearchIcon } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { Empty, EmptyDescription } from "@/components/ui/empty";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import { cn } from "@/lib/utils";
import type { ConversationSummary } from "@/actions/chat";

interface ConversationSidebarProps {
  conversations: ConversationSummary[];
  /** The conversation on screen, highlighted and never filtered out. */
  activeId: string;
}

type Bucket = "today" | "week" | "month" | "older";

const BUCKET_ORDER: Bucket[] = ["today", "week", "month", "older"];

function bucketFor(updatedAt: string, now: number): Bucket {
  const ageMs = now - new Date(updatedAt).getTime();
  const day = 24 * 60 * 60 * 1000;
  if (ageMs < day) return "today";
  if (ageMs < 7 * day) return "week";
  if (ageMs < 30 * day) return "month";
  return "older";
}

export function ConversationSidebar({
  conversations,
  activeId,
}: ConversationSidebarProps) {
  const t = useTranslations("chat");
  const [query, setQuery] = useState("");

  const grouped = useMemo(() => {
    const needle = query.trim().toLowerCase();
    // `Date.now()` inside the memo, not during render, keeps the
    // bucket boundaries stable for a given filter pass.
    const now = Date.now();

    const matches = conversations.filter((conversation) => {
      if (!needle) return true;
      return (conversation.title ?? "").toLowerCase().includes(needle);
    });

    const buckets = new Map<Bucket, ConversationSummary[]>();
    for (const conversation of matches) {
      const bucket = bucketFor(conversation.updatedAt, now);
      buckets.set(bucket, [...(buckets.get(bucket) ?? []), conversation]);
    }
    return buckets;
  }, [conversations, query]);

  const empty = BUCKET_ORDER.every((bucket) => !grouped.get(bucket)?.length);

  return (
    <aside className="hidden w-64 shrink-0 flex-col border-r lg:flex">
      <div className="space-y-2 border-b p-3">
        <Button
          size="sm"
          className="w-full justify-start gap-2"
          render={<Link href="/chat" />}
          nativeButton={false}
        >
          <PlusIcon data-icon="inline-start" />
          {t("header.newChat")}
        </Button>

        <InputGroup>
          <InputGroupAddon>
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={t("sidebar.searchPlaceholder")}
            aria-label={t("sidebar.searchPlaceholder")}
          />
        </InputGroup>
      </div>

      <nav
        aria-label={t("sidebar.label")}
        className="flex-1 overflow-y-auto px-2 py-3"
      >
        {empty ? (
          <Empty className="p-4">
            <EmptyDescription>
              {query ? t("sidebar.noMatches") : t("header.historyEmpty")}
            </EmptyDescription>
          </Empty>
        ) : (
          BUCKET_ORDER.map((bucket) => {
            const items = grouped.get(bucket);
            if (!items?.length) return null;
            return (
              <div key={bucket} className="mb-4">
                <p className="px-2 pb-1 text-xs font-medium text-muted-foreground">
                  {t(`sidebar.groups.${bucket}`)}
                </p>
                <ul>
                  {items.map((conversation) => {
                    const isActive = conversation.id === activeId;
                    return (
                      <li key={conversation.id}>
                        <Link
                          href={`/chat/${conversation.id}`}
                          aria-current={isActive ? "page" : undefined}
                          className={cn(
                            "flex items-center gap-2 rounded-md px-2 py-1.5 text-sm transition-colors",
                            isActive
                              ? "bg-accent font-medium"
                              : "hover:bg-accent/50"
                          )}
                          title={
                            conversation.title ?? t("header.historyUntitled")
                          }
                        >
                          <MessageSquareIcon
                            className="size-3.5 shrink-0 text-muted-foreground"
                            aria-hidden
                          />
                          <span className="truncate">
                            {conversation.title ?? t("header.historyUntitled")}
                          </span>
                        </Link>
                      </li>
                    );
                  })}
                </ul>
              </div>
            );
          })
        )}
      </nav>

      <p className="border-t px-3 py-2 text-xs text-muted-foreground">
        {t("sidebar.count", { count: conversations.length })}
      </p>
    </aside>
  );
}

