/**
 * Chat composition config — the consumer-owned extension point for
 * everything a vertical wants to add to the chat surface without
 * editing `components/chat/chat-panel.tsx` or
 * `components/chat/conversation-header.tsx` (ADR-0005: composition
 * through a config a consumer owns, never a component edit).
 *
 * Three seams, all optional — a fresh install ships this file with an
 * empty `chatConfig`, so the chat surface renders nothing extra beyond
 * its baseline UI:
 *
 *  - `agent`: the identity shown in the conversation header — a
 *    name and optional icon/emoji. Omit it (the default) and the
 *    header falls back to this item's own translated "Assistant"
 *    label (`messages/en/chat.json`'s `agent.defaultName`) — that
 *    fallback is why `name`/`icon` are plain strings here rather than
 *    routed through this item's messages file: once you bind your own
 *    product's agent identity, its copy is your product's copy to
 *    localize however you like — the agent's display name is product
 *    copy, not framework copy.
 *  - `starters`: conversation-starter prompts shown on an empty
 *    conversation, as *message keys* — not literal strings — resolved
 *    against your app's full message tree via next-intl's
 *    namespace-less `useTranslations()`. E.g. `"support.starters.refund"`
 *    resolves `t("support.starters.refund")` from your own
 *    `messages/<locale>/support.json`. Keeping this to keys (never
 *    literal display text) is what keeps starters translatable without
 *    editing `chat-panel.tsx`. Default: no starters — the empty-state
 *    card just shows its title and description.
 *  - `headerRight`: a component `conversation-header.tsx` renders on
 *    the right side of the header, next to the History/New/Delete
 *    controls, e.g. a progress indicator or an export button reading
 *    product state for `conversationId`. Default: nothing extra.
 *
 * Edit this file directly to point at your product's own components —
 * this is consumer-owned source, not a package import. Example, once
 * you have a product-specific header component:
 *
 *   import { ExportReportButton } from "@/components/support/export-report-button";
 *
 *   export const chatConfig: ChatConfig = {
 *     agent: { id: "support-assistant", name: "Support Assistant", icon: "🎧" },
 *     starters: ["support.starters.refund", "support.starters.shipping"],
 *     headerRight: ExportReportButton,
 *   };
 */

import type { ComponentType } from "react";
import type { UIMessage } from "ai";

/** Props passed to a consumer-bound `headerRight` component. */
export interface ChatHeaderRightProps {
  conversationId: string;
}

export interface ChatAgentIdentity {
  /** Stable id for the agent this chat surface represents. */
  id?: string;
  /** Display name. Falls back to this item's translated default when omitted. */
  name?: string;
  /** A short icon or emoji shown beside the name. */
  icon?: string;
}

export interface ChatConfig {
  /** Identity shown in the conversation header. Omit for the default "Assistant" label. */
  agent?: ChatAgentIdentity;
  /** Conversation-starter message keys — see the module doc comment above. */
  starters?: string[];
  /** Rendered on the right side of the conversation header. */
  headerRight?: ComponentType<ChatHeaderRightProps>;
  /**
   * Auto-continuation predicate, passed straight to `useChat`'s
   * `sendAutomaticallyWhen`. A product whose tools advance the
   * conversation without user input (e.g. a selection tool that should
   * immediately trigger the next assistant turn) binds its predicate
   * here. Default: no automatic sends.
   */
  sendAutomaticallyWhen?: (options: {
    messages: UIMessage[];
  }) => boolean | PromiseLike<boolean>;
}

/**
 * Default chat configuration — a fresh install has no product identity,
 * starters, or header component to add.
 */
export const chatConfig: ChatConfig = {};

"use client";

/**
 * Error boundary for a chat conversation. Renders the shared `RouteError` from the
 * `route-error` item — install it alongside this one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <RouteError
      error={error}
      reset={reset}
      scope="chat-conversation"
      fallback="conversation"
      homeHref="/chat"
      homeKey="goToChat"
    />
  );
}

import "server-only";

/**
 * Server-side chat config — consumer-owned, read by
 * `app/api/chat/route.ts` through `createChatHandler`.
 *
 * Separate from `lib/chat-config.tsx` on purpose: that file is
 * client-facing (it binds React components — a header slot, starter
 * keys, an agent identity), and importing it from the Route Handler
 * would drag client modules into the server bundle. Everything the
 * transport needs and the browser must never see lives here instead.
 *
 * Two fields are required — the execution boundary and a way to turn
 * a model id into a model — because those are the two things the
 * framework must never guess. Everything else has a default that gives
 * a fresh install a working chat with no API keys: one agent, one
 * prompt, no tools, a forty-message window, a truncated first line as
 * the title.
 *
 * The seam that matters most is `agent.tools`. Without it the model
 * runs with no tools, which makes the tool-renderer seam in
 * `lib/chat-renderers.tsx` unreachable — you could register a renderer
 * but nothing would ever call a tool for it to render. Bind tools here
 * and the whole path works without editing a shipped file:
 *
 *   import { tool } from "ai";
 *   import { z } from "zod";
 *
 *   agent: {
 *     systemPrompt: "…",
 *     tools: ({ workspaceId }) => ({
 *       searchDocs: tool({
 *         description: "Search the workspace's documents",
 *         inputSchema: z.object({ query: z.string() }),
 *         execute: async ({ query }) => search(workspaceId, query),
 *       }),
 *     }),
 *   },
 *
 * `tools` may be a plain `ToolSet` or a function of the turn (workspace,
 * user, conversation) — the function form is what lets a tool close
 * over the caller's tenancy instead of taking it as a model argument
 * the model could get wrong.
 *
 * Past one agent, bind `resolveAgent` instead of `agent`: it receives
 * the turn (the transport's extra body fields such as `agentId`, the
 * existing conversation row) and returns the prompt, tools and model
 * for this turn. `prepareMessages` decides what the model is shown —
 * windowing is the default; a product that summarises pruned history
 * or injects profile context does it there. See `ChatServerConfig` in
 * `@intelligo-dev/chat` for every seam.
 *
 * i18n: the route lives at `app/api/chat/route.ts`, outside the
 * `[locale]` segment (ADR-0010), so there is no URL segment to read a
 * locale from. `messages` below reads the `NEXT_LOCALE` cookie
 * next-intl's middleware already sets on every page navigation, then
 * falls back to the configured default locale — the same "works with
 * nothing extra" guarantee a single-locale deployment gets everywhere
 * else.
 */

import type { ChatMessages, ChatServerConfig } from "@intelligo-dev/chat";
import { getTranslations } from "next-intl/server";

import { routing } from "@/i18n/routing";
import { CHAT_MODEL_ID, getChatModel } from "@/lib/chat-model";
import { composeIntelligo, executions } from "@/lib/intelligo";

function localeFrom(request: Request): string {
  const cookieName =
    typeof routing.localeCookie === "object"
      ? (routing.localeCookie.name ?? "NEXT_LOCALE")
      : "NEXT_LOCALE";
  const cookie = request.headers.get("cookie") ?? "";
  const match = cookie.match(new RegExp(`(?:^|;\\s*)${cookieName}=([^;]+)`));
  const value = match?.[1] ? decodeURIComponent(match[1]) : undefined;
  const locales: readonly string[] = routing.locales;
  return value && locales.includes(value) ? value : routing.defaultLocale;
}

/** Refusal copy from this item's `chat` namespace, in the caller's locale. */
async function chatMessages(request: Request): Promise<ChatMessages> {
  const t = await getTranslations({
    locale: localeFrom(request),
    namespace: "chat",
  });
  return (key, params) => t(`route.${key}`, params);
}

export const chatServerConfig: ChatServerConfig = {
  executions,
  onRequest: composeIntelligo,
  model: { defaultId: CHAT_MODEL_ID, resolve: getChatModel },
  messages: chatMessages,

  featureKey: "chat",
  capability: "chat.message",
  maxMessageLength: 8000,
  maxSteps: 5,

  agent: {
    id: "assistant",
    systemPrompt:
      "You are a helpful assistant embedded in a SaaS product. Be concise and direct.",
  },
};

import "server-only";

/**
 * What the chat page knows about the caller's credit before they type.
 *
 * The transport already refuses a turn it cannot fund — admission runs
 * inside `executions.begin()` and answers 402. That is the correct
 * enforcement point and the wrong place to *tell someone*: by then they
 * have written a message and watched it fail. This is the read that
 * lets the page say so first — an estimate, never a reservation, priced
 * against the model a turn would run on.
 */

import { getChatQuotaState as readChatQuotaState } from "@intelligo-dev/chat";
import type { ChatQuotaState } from "@intelligo-dev/chat/client";

import { CHAT_MODEL_ID } from "@/lib/chat-model";

export type { ChatQuotaState };

/** Never throws: a quota read that fails costs the reader a banner, not the conversation. */
export function getChatQuotaState(): Promise<ChatQuotaState | null> {
  return readChatQuotaState({
    modelId: CHAT_MODEL_ID,
    upgradeHref: "/pricing",
  });
}

"use client";

/**
 * Tells the reader about their credit before they spend a message on
 * finding out.
 *
 * Two states, and both matter:
 *
 *   - **blocked** — the next turn will be refused. Server-rendered
 *     from `getChatQuotaState()`, or seeded from the route's own 402
 *     when the balance runs out mid-conversation.
 *   - **running low** — allowed, but one more turn would take most of
 *     what is left. A warning nobody asked for beats a refusal nobody
 *     expected.
 *
 * Copy lives in this item's `chat` namespace, not in props. The
 * product-side version of this component took a `CreditBannerStrings`
 * object with English defaults, because it lived in a package and a
 * package cannot reach next-intl — which also meant its defaults
 * hardcoded a currency symbol and a language. An item has no such
 * problem (ADR-0010).
 *
 * Amounts are credits, not money. That is the unit the balance and the
 * estimate are both in; rendering it as currency would need an
 * exchange rate this component has no business choosing.
 */

import { AlertTriangleIcon, SparklesIcon } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import type { ChatQuotaState } from "@intelligo-dev/chat/client";

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Link } from "@/i18n/navigation";

/**
 * What the page opened with, read by `getChatQuotaState()`. The shape
 * is the transport's (`@intelligo-dev/chat/client`, which imports
 * nothing, so a client component can read it without pulling a server
 * module into its graph). Re-exported so `lib/chat-quota.ts` and the
 * page name it from the component that renders it.
 */
export type { ChatQuotaState };

/**
 * A refusal that arrived from the route mid-conversation, rather than
 * from the server render.
 */
export type ChatBlock = {
  code: string;
  message: string;
};

interface CreditStatusBannerProps {
  quotaState: ChatQuotaState | null;
  block: ChatBlock | null;
}

export function CreditStatusBanner({
  quotaState,
  block,
}: CreditStatusBannerProps) {
  const t = useTranslations("chat");
  const format = useFormatter();

  // A block from the route wins: it is the newer fact. The
  // server-rendered state is what the page opened with, and the reader
  // may have spent their last credits since.
  const refusal: ChatBlock | null =
    block ??
    (quotaState && !quotaState.allowed
      ? { code: quotaState.code ?? "", message: quotaState.reason ?? "" }
      : null);

  if (refusal) {
    return (
      <Alert
        variant="destructive"
        data-testid="credit-status-banner"
        className="mx-auto mb-2 w-full max-w-3xl"
      >
        <AlertTriangleIcon />
        <AlertTitle>
          {refusal.code === "insufficient_credits" ||
          refusal.code === "allowance_depleted"
            ? t("creditBanner.outOfCredits")
            : t("creditBanner.upgradeRequired")}
        </AlertTitle>
        {refusal.message ? (
          <AlertDescription>{refusal.message}</AlertDescription>
        ) : null}
        <AlertAction>
          <Button
            size="sm"
            variant="destructive"
            render={<Link href={quotaState?.upgradeHref ?? "/pricing"} />}
            nativeButton={false}
          >
            {t("creditBanner.upgrade")}
          </Button>
        </AlertAction>
      </Alert>
    );
  }

  // "Running low" is one turn's worth of headroom, not a percentage: a
  // share of a large allowance can still be plenty, while twice the
  // estimate is exactly the point where the next message might be the
  // last one.
  const runningLow =
    quotaState !== null &&
    quotaState.allowed &&
    quotaState.estimated > 0 &&
    quotaState.remaining < quotaState.estimated * 2;

  if (!runningLow || !quotaState) return null;

  return (
    <Alert
      role="status"
      data-testid="credit-status-warning"
      className="mx-auto mb-2 w-full max-w-3xl border-warning/30 bg-warning/10 text-warning"
    >
      <SparklesIcon />
      <AlertTitle>
        {t("creditBanner.runningLow", {
          count: quotaState.remaining,
          amount: format.number(quotaState.remaining),
        })}
      </AlertTitle>
      <AlertAction>
        <Button
          size="xs"
          variant="ghost"
          className="text-warning hover:text-warning"
          render={<Link href={quotaState.upgradeHref} />}
          nativeButton={false}
        >
          {t("creditBanner.topUp")}
        </Button>
      </AlertAction>
    </Alert>
  );
}
